# Mean-shift alignment for cross-lingual activation spaces.
# Shifts target-language activations to match source-language mean.
# Inputs/outputs: (N, D) tensors or numpy arrays.

import torch
import numpy as np


def _to_tensor(x) -> torch.Tensor:
    if isinstance(x, np.ndarray):
        return torch.from_numpy(x).float()
    return x.float()


def compute_mean_shift(
    source_activations: torch.Tensor,
    target_activations: torch.Tensor,
) -> torch.Tensor:
    """Compute mean difference between target and source activations.

    Returns:
        shift: (D,) tensor = mean(target) - mean(source)
    """
    src = _to_tensor(source_activations)
    tgt = _to_tensor(target_activations)
    return tgt.mean(dim=0) - src.mean(dim=0)


def apply_mean_shift(
    activations: torch.Tensor,
    shift: torch.Tensor,
) -> torch.Tensor:
    """Align activations by subtracting the mean shift.

    aligned = activations - shift, moving target-language mean toward source.
    """
    act = _to_tensor(activations)
    s = _to_tensor(shift)
    return act - s
